<template>
  <div 
    class="fixed inset-0 bg-black/60 flex justify-center items-center z-50 transition duration-300"
    :class="showshop ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'"
  >

    <!-- 主視窗容器 -->
    <div class="bg-gray-900/90 w-[80%] max-w-5xl p-8 rounded-2xl shadow-2xl border border-yellow-600 flex flex-col items-center">

      <!-- 商店標題 -->
       <div class="flex justify-between items-center mb-8 w-full">
         <div class="text-4xl font-bold mb-8 text-yellow-300 drop-shadow-lg">
        🏪 商店
        </div>
        <div class="text-4xl font-bold mb-8 text-yellow-300 drop-shadow-lg">
        🪙 金幣:{{ player.coin }}
        </div>
       </div>

      <!-- 三大區塊 -->
      <div class="w-full space-y-12 overflow-y-auto max-h-[70vh] pr-2">

        <!-- 第一排：卡牌商店 -->
        <section class="bg-gray-800/60 p-6 rounded-xl shadow-lg border border-gray-700">
          <h2 class="text-2xl font-bold mb-5 text-blue-300">📘 卡牌區</h2>

          <div class="grid grid-cols-5 gap-6">
            <template v-if="cardsForSale.length > 0">
              <div 
                v-for="(card, index) in cardsForSale" 
                :key="card.id + '-' + index"
                class="relative group" 
              >
                <GameCard 
                  :card="card" 
                  @play="buyCard(card)"
                  class="transform hover:scale-110 transition duration-200"
                />
                
                <div class="text-center text-yellow-300 text-lg mt-2 font-bold">
                  🪙 {{ card.price }}
                </div>
              </div>
            </template>
            <template v-else>
                <div class="col-span-5 text-center text-gray-400 text-lg">
                  售完
                </div>
            </template>
          </div>
        </section>

        <!-- 第二排：裝備商店 -->
        <section class="bg-gray-800/60 p-6 rounded-xl shadow-lg border border-gray-700">
          <h2 class="text-2xl font-bold mb-5 text-green-300">🛡 裝備區</h2>

          <div class="grid grid-cols-5 gap-6">
            <template v-if="equipsForSale.length > 0">
              <div
                v-for="(equip, index) in equipsForSale"
                :key="equip.id + '-' + index"
                class="relative group"
              >
                <Equip
                  :equip="equip"
                  @buy="buyEquip(equip, index)"
                  class="transform hover:scale-110 transition duration-200"
                />
                
                <div class="text-center text-yellow-300 text-lg mt-2 font-bold">
                  🪙 {{ equip.price }}
                </div>
              </div>
            </template>
            <template v-else>
              <div class="col-span-5 text-center text-gray-400 text-lg">
                售完
              </div>
            </template>
          </div>
        </section>

        <!-- 第三排：藥水商店 -->
        <section class="bg-gray-800/60 p-6 rounded-xl shadow-lg border border-gray-700">
          <h2 class="text-2xl font-bold mb-5 text-blue-300">🧪 藥水區</h2>

          <div class="grid grid-cols-5 gap-6">
            <template v-if="potionsForSale.length > 0">
              <div
                v-for="(potion, index) in potionsForSale"
                :key="potion.id + '-' + index"
                class="relative group"
              >
                <Item 
                  :item="potion" 
                  :count="1" 
                  @use="buyPotion(potion)"
                  class="transform hover:scale-110 transition duration-200"
                />
                <div class="text-center text-yellow-300 text-lg mt-2 font-bold">
                  🪙 {{ potion.price }}
                </div>
              </div>
            </template>
            <template v-else>
              <div class="col-span-5 text-center text-gray-400 text-lg">
                售完
              </div>
            </template>
          </div>
        </section>
      </div>

      <!-- 返回按鈕 -->
      <button
        @click="$emit('close-shop')"
        class="mt-8 px-10 py-3 bg-yellow-600 rounded-xl hover:bg-yellow-500 text-lg font-bold shadow-lg"
      >
        返回
      </button>

    </div>

  </div>
</template>

<script>
import GameCard from "./Card.vue";
import Item from "./Item.vue";
import Equip from "./Equip.vue";

export default {
  name: "GameShop",
  components: { GameCard, Item, Equip },
  props: {
    player: Object,
    potions: Object,
    cards: Object,
    equipments: Object,
    showshop: Boolean
  },
  data() {
    return {
      cardsForSale: [],
      potionsForSale: [],
      equipsForSale: []
    }
  },
  methods: {
    generateShopItems() {
      //卡牌
      let jobCards = {};
      if (this.player.job === "warrior") jobCards = this.cards.warrior;
      else if (this.player.job === "mage") jobCards = this.cards.mage;
      else if (this.player.job === "archer") jobCards = this.cards.archer; 

      const allCardsMap = { ...jobCards, ...this.cards.common };
      const cardKeys = Object.keys(allCardsMap);

      const cardCandidates = cardKeys.filter(key => {
        const card = allCardsMap[key];
        
        const isSellable = (card.isSell !== false);
        
        const chance = (card.chance !== undefined) ? card.chance : 1;
        const isLucky = Math.random() < chance;

        return isSellable && isLucky;
      });

      this.cardsForSale = [];
      for (let i = 0; i < 5; i++) {
        if (cardCandidates.length === 0) break; 

        const randomIndex = Math.floor(Math.random() * cardCandidates.length);
        const key = cardCandidates[randomIndex];
        const card = allCardsMap[key];

        this.cardsForSale.push({
          ...card,
          price: card.price
        });
      }

      //裝備
      this.equipsForSale = [];
      const equipKeys = Object.keys(this.equipments);
      const candidates = equipKeys.filter(key => {
        const equip = this.equipments[key];
        const isSellable = (equip.isSell !== false);
        const chance = (equip.chance !== undefined) ? equip.chance : 1;
        const isLucky = Math.random() < chance;

        return isSellable && isLucky;
      });
      for(let i = 0; i < 5; i++) {
        if (candidates.length === 0) break;

        const randomIndex = Math.floor(Math.random() * candidates.length);
        const key = candidates[randomIndex];
        const equip = this.equipments[key];

        this.equipsForSale.push({
          ...equip,
          price: equip.price
        });
      }

      // 藥水
      this.potionsForSale = []; 
        const potionKeys = Object.keys(this.potions); 

        const potionCandidates = potionKeys.filter(key => {
          const potion = this.potions[key];

          const isSellable = (potion.isSell !== false);

          const chance = (potion.chance !== undefined) ? potion.chance : 1;
          const isLucky = Math.random() < chance;

          return isSellable && isLucky;
        });

        for(let i = 0; i < 5; i++) { 
          if (potionCandidates.length === 0) break;

          const randomIndex = Math.floor(Math.random() * potionCandidates.length); 
          const key = potionCandidates[randomIndex]; 
          const potion = this.potions[key]; 
          
          this.potionsForSale.push({ 
            ...potion,
            price: potion.price
          });
        }
    },

    buyCard(card) {
      this.$emit("buy-card", card.id, card.price, this.cardsForSale);
    },

    buyEquip(equip, index) {
      this.$emit("buy-equip", equip ,index, this.equipsForSale);
    },

    buyPotion(potion) {
      this.$emit("buy-potion", potion.id, potion.price, this.potionsForSale);
    },
  },
  watch: {
    'player.job'(newJob) {
      if(newJob) {
        this.generateShopItems();
      }
    }
  }
}
</script>
